        command = shlex.join(("python3", "-c", runner, payload))
        result = node.execute(command, shell=False, timeout=900)
        detail = (result.stdout + "\n" + result.stderr).strip()
        assert_that(result.exit_code).described_as(detail).is_equal_to(0)
